-- SEÇÃO: Geometria
select public.fj_seed_q('mat', 'mat:areas', 'mat:areas:1', 0, 'mc', $q$Um terreno retangular tem 20 m de comprimento e 15 m de largura. Quantos metros de cerca são necessários para contornar todo o terreno?$q$, $j${"opts":["70 m","35 m","300 m","50 m"],"a":0}$j$, $q$O perímetro do retângulo é 2 × (20 + 15) = 70 m.$q$, 1);
select public.fj_seed_q('mat', 'mat:areas', 'mat:areas:1', 1, 'mc', $q$Uma praça quadrada tem perímetro de 48 m. Quanto mede cada lado?$q$, $j${"opts":["12 m","24 m","16 m","8 m"],"a":0}$j$, $q$No quadrado, o perímetro é 4 vezes o lado: 48 ÷ 4 = 12 m.$q$, 2);
select public.fj_seed_q('mat', 'mat:areas', 'mat:areas:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"O comprimento de uma circunferência é calculado por C = 2πr.","a":true}$j$, $q$Verdadeiro: o contorno do círculo é 2π vezes o raio.$q$, 1);
select public.fj_seed_q('mat', 'mat:areas', 'mat:areas:1', 3, 'match', $q$Associe a figura à fórmula do seu perímetro$q$, $j${"pairs":[["Quadrado de lado L","4L"],["Retângulo de base b e altura h","2(b + h)"],["Triângulo equilátero de lado L","3L"],["Circunferência de raio r","2πr"]]}$j$, $q$O perímetro é a soma dos lados; na circunferência, usa-se 2πr.$q$, 2);
select public.fj_seed_q('mat', 'mat:areas', 'mat:areas:2', 0, 'mc', $q$Uma parede retangular de 4 m de comprimento por 3 m de altura será pintada. Qual é a área a pintar?$q$, $j${"opts":["12 m²","7 m²","14 m²","24 m²"],"a":0}$j$, $q$A área do retângulo é base vezes altura: 4 × 3 = 12 m².$q$, 1);
select public.fj_seed_q('mat', 'mat:areas', 'mat:areas:2', 1, 'mc', $q$Um triângulo tem base de 10 cm e altura de 6 cm. Qual é a sua área?$q$, $j${"opts":["30 cm²","60 cm²","16 cm²","15 cm²"],"a":0}$j$, $q$A área do triângulo é (base × altura) ÷ 2: (10 × 6) ÷ 2 = 30 cm².$q$, 2);
select public.fj_seed_q('mat', 'mat:areas', 'mat:areas:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"A área de um quadrado de lado 5 cm é 20 cm².","a":false}$j$, $q$Falso: a área é lado × lado, ou seja, 5 × 5 = 25 cm²; 20 cm é o perímetro.$q$, 2);
select public.fj_seed_q('mat', 'mat:areas', 'mat:areas:2', 3, 'bank', $q$Complete a frase$q$, $j${"parts":["A área do retângulo é base vezes ",", e a área do triângulo é base vezes altura dividido por ","."],"a":["altura","dois"],"extra":["perímetro","quatro"]}$j$, $q$Retângulo: b × h. Triângulo: (b × h) ÷ 2, pois é metade de um retângulo.$q$, 1);
select public.fj_seed_q('mat', 'mat:solidos', 'mat:solidos:1', 0, 'mc', $q$Uma caixa d'água em forma de cubo tem aresta de 2 m. Qual é o seu volume?$q$, $j${"opts":["8 m³","4 m³","6 m³","12 m³"],"a":0}$j$, $q$O volume do cubo é aresta ao cubo: 2 × 2 × 2 = 8 m³.$q$, 1);
select public.fj_seed_q('mat', 'mat:solidos', 'mat:solidos:1', 1, 'mc', $q$Uma piscina em forma de paralelepípedo tem 8 m de comprimento, 5 m de largura e 2 m de profundidade. Qual é o seu volume?$q$, $j${"opts":["80 m³","40 m³","15 m³","160 m³"],"a":0}$j$, $q$O volume do paralelepípedo é comprimento × largura × altura: 8 × 5 × 2 = 80 m³.$q$, 2);
select public.fj_seed_q('mat', 'mat:solidos', 'mat:solidos:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Um volume de 1 m³ equivale a 1.000 litros.","a":true}$j$, $q$Verdadeiro: 1 m³ = 1.000 dm³, e cada dm³ corresponde a 1 litro.$q$, 2);
select public.fj_seed_q('mat', 'mat:solidos', 'mat:solidos:1', 3, 'order', $q$Ordene os recipientes do menor para o maior volume$q$, $j${"items":["Cubo de aresta 1 m","Caixa de 2 m × 1 m × 1 m","Cubo de aresta 2 m","Caixa de 5 m × 2 m × 1 m"]}$j$, $q$Os volumes são 1 m³, 2 m³, 8 m³ e 10 m³, nessa ordem.$q$, 3);
select public.fj_seed_q('mat', 'mat:solidos', 'mat:solidos:2', 0, 'mc', $q$Um triângulo retângulo tem catetos de 6 cm e 8 cm. Quanto mede a hipotenusa?$q$, $j${"opts":["10 cm","14 cm","12 cm","9 cm"],"a":0}$j$, $q$Por Pitágoras: 6² + 8² = 36 + 64 = 100, e a raiz de 100 é 10 cm.$q$, 1);
select public.fj_seed_q('mat', 'mat:solidos', 'mat:solidos:2', 1, 'mc', $q$Uma escada de 5 m está apoiada em um muro, com o pé a 3 m da base do muro. Que altura do muro a escada alcança?$q$, $j${"opts":["4 m","2 m","5 m","3,5 m"],"a":0}$j$, $q$Por Pitágoras: 5² − 3² = 25 − 9 = 16, e a raiz de 16 é 4 m.$q$, 2);
select public.fj_seed_q('mat', 'mat:solidos', 'mat:solidos:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Em todo triângulo retângulo, o quadrado da hipotenusa é igual à soma dos quadrados dos catetos.","a":true}$j$, $q$Verdadeiro: esse é exatamente o enunciado do Teorema de Pitágoras.$q$, 1);
select public.fj_seed_q('mat', 'mat:solidos', 'mat:solidos:2', 3, 'match', $q$Associe o tipo de ângulo à sua medida$q$, $j${"pairs":[["Ângulo reto","Mede exatamente 90°"],["Ângulo agudo","Mede menos de 90°"],["Ângulo obtuso","Mede mais de 90° e menos de 180°"],["Ângulo raso","Mede exatamente 180°"]]}$j$, $q$A classificação dos ângulos é feita comparando a medida com 90° e 180°.$q$, 2);

-- SEÇÃO: Estatística e probabilidade
select public.fj_seed_q('mat', 'mat:medidas', 'mat:medidas:1', 0, 'mc', $q$As notas de um aluno no bimestre foram 6, 8, 7 e 9. Qual é a média dessas notas?$q$, $j${"opts":["7,5","7","8","7,2"],"a":0}$j$, $q$A média é a soma dividida pela quantidade: (6 + 8 + 7 + 9) ÷ 4 = 30 ÷ 4 = 7,5.$q$, 1);
select public.fj_seed_q('mat', 'mat:medidas', 'mat:medidas:1', 1, 'mc', $q$Qual é a mediana do conjunto de dados 2, 3, 3, 5, 7, 10?$q$, $j${"opts":["4","3","5","4,5"],"a":0}$j$, $q$Com 6 valores ordenados, a mediana é a média dos dois centrais: (3 + 5) ÷ 2 = 4.$q$, 3);
select public.fj_seed_q('mat', 'mat:medidas', 'mat:medidas:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"A moda de um conjunto de dados é o valor que aparece com mais frequência.","a":true}$j$, $q$Verdadeiro: a moda é o valor mais repetido; um conjunto pode até ter mais de uma moda.$q$, 1);
select public.fj_seed_q('mat', 'mat:medidas', 'mat:medidas:1', 3, 'bank', $q$Complete a frase$q$, $j${"parts":["A "," é a soma dos valores dividida pela quantidade, e a "," é o valor central dos dados ordenados."],"a":["média","mediana"],"extra":["moda","amplitude"]}$j$, $q$Média: soma ÷ quantidade. Mediana: valor do meio dos dados em ordem.$q$, 2);
select public.fj_seed_q('mat', 'mat:medidas', 'mat:medidas:2', 0, 'mc', $q$Em uma pesquisa com 200 pessoas, 40 escolheram suco como bebida favorita. Que percentual isso representa?$q$, $j${"opts":["20%","40%","25%","15%"],"a":0}$j$, $q$40 em 200 é 40 ÷ 200 = 0,20, ou seja, 20%.$q$, 1);
select public.fj_seed_q('mat', 'mat:medidas', 'mat:medidas:2', 1, 'mc', $q$A média de idade de 4 amigos é 15 anos. Um quinto amigo, de 20 anos, entra no grupo. Qual passa a ser a média de idade?$q$, $j${"opts":["16 anos","17 anos","17,5 anos","15,5 anos"],"a":0}$j$, $q$A soma das idades era 4 × 15 = 60; com o novo amigo, (60 + 20) ÷ 5 = 16 anos.$q$, 3);
select public.fj_seed_q('mat', 'mat:medidas', 'mat:medidas:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Se a média das notas de uma turma foi 7, então todos os alunos tiraram nota 7.","a":false}$j$, $q$Falso: a média resume o conjunto, mas as notas individuais podem variar bastante.$q$, 2);
select public.fj_seed_q('mat', 'mat:medidas', 'mat:medidas:2', 3, 'order', $q$Ordene as etapas de uma pesquisa estatística$q$, $j${"items":["Definir a pergunta e o público pesquisado","Coletar os dados","Organizar os dados em tabelas e gráficos","Interpretar os resultados e concluir"]}$j$, $q$Primeiro se planeja, depois coleta-se, organiza-se e só então se interpreta.$q$, 2);
select public.fj_seed_q('mat', 'mat:probabilidade', 'mat:probabilidade:1', 0, 'mc', $q$Uma urna tem 3 bolas vermelhas e 7 bolas azuis. Qual é a probabilidade de sortear uma bola vermelha?$q$, $j${"opts":["30%","70%","3%","50%"],"a":0}$j$, $q$São 3 casos favoráveis em 10 possíveis: 3/10 = 30%.$q$, 1);
select public.fj_seed_q('mat', 'mat:probabilidade', 'mat:probabilidade:1', 1, 'mc', $q$Ao lançar um dado comum de 6 faces, qual é a probabilidade de sair um número maior que 4?$q$, $j${"opts":["1/3","1/2","2/3","1/6"],"a":0}$j$, $q$Os casos favoráveis são 5 e 6, ou seja, 2 em 6, que simplifica para 1/3.$q$, 2);
select public.fj_seed_q('mat', 'mat:probabilidade', 'mat:probabilidade:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Ao lançar uma moeda honesta duas vezes, a probabilidade de sair cara nas duas é 1/4.","a":true}$j$, $q$Verdadeiro: os lançamentos são independentes, então 1/2 × 1/2 = 1/4.$q$, 2);
select public.fj_seed_q('mat', 'mat:probabilidade', 'mat:probabilidade:1', 3, 'match', $q$Associe o conceito de probabilidade à sua definição$q$, $j${"pairs":[["Espaço amostral","Conjunto de todos os resultados possíveis"],["Evento certo","Probabilidade igual a 1"],["Evento impossível","Probabilidade igual a 0"],["Probabilidade de um evento","Casos favoráveis divididos por casos possíveis"]]}$j$, $q$A probabilidade sempre varia de 0 (impossível) a 1 (certo).$q$, 2);
select public.fj_seed_q('mat', 'mat:probabilidade', 'mat:probabilidade:2', 0, 'mc', $q$Uma lanchonete oferece 3 tipos de pão e 4 tipos de recheio. Quantos sanduíches diferentes podem ser montados?$q$, $j${"opts":["12","7","34","4"],"a":0}$j$, $q$Pelo princípio multiplicativo: 3 × 4 = 12 combinações.$q$, 1);
select public.fj_seed_q('mat', 'mat:probabilidade', 'mat:probabilidade:2', 1, 'mc', $q$De quantas maneiras diferentes 4 livros podem ser organizados lado a lado em uma prateleira?$q$, $j${"opts":["24","16","12","4"],"a":0}$j$, $q$São 4 opções para o primeiro lugar, 3 para o segundo, 2 e 1: 4 × 3 × 2 × 1 = 24.$q$, 2);
select public.fj_seed_q('mat', 'mat:probabilidade', 'mat:probabilidade:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Com os algarismos 1, 2 e 3, sem repetição, é possível formar 6 números de três algarismos.","a":true}$j$, $q$Verdadeiro: 3 × 2 × 1 = 6 números diferentes.$q$, 2);
select public.fj_seed_q('mat', 'mat:probabilidade', 'mat:probabilidade:2', 3, 'bank', $q$Complete a frase$q$, $j${"parts":["Com 2 bermudas e 5 camisetas, há "," combinações de roupa; já 3 pessoas podem formar uma fila de "," maneiras diferentes."],"a":["10","6"],"extra":["7","9"]}$j$, $q$Multiplicam-se as possibilidades: 2 × 5 = 10 e 3 × 2 × 1 = 6.$q$, 3);

-- SEÇÃO: Matemática financeira
select public.fj_seed_q('mat', 'mat:juros', 'mat:juros:1', 0, 'mc', $q$Um empréstimo de R$ 1.000 é feito a juros simples de 2% ao mês. Quanto rende de juros em 5 meses?$q$, $j${"opts":["R$ 100","R$ 110","R$ 50","R$ 200"],"a":0}$j$, $q$Juros simples: J = C · i · t = 1.000 × 0,02 × 5 = R$ 100.$q$, 1);
select public.fj_seed_q('mat', 'mat:juros', 'mat:juros:1', 1, 'mc', $q$Aplicando R$ 500 a juros simples de 3% ao mês durante 4 meses, qual será o montante final?$q$, $j${"opts":["R$ 560","R$ 515","R$ 600","R$ 530"],"a":0}$j$, $q$Os juros são 500 × 0,03 × 4 = R$ 60; o montante é 500 + 60 = R$ 560.$q$, 2);
select public.fj_seed_q('mat', 'mat:juros', 'mat:juros:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"No regime de juros simples, os juros de cada período são calculados sempre sobre o valor inicial.","a":true}$j$, $q$Verdadeiro: nos juros simples a base de cálculo é sempre o capital inicial.$q$, 1);
select public.fj_seed_q('mat', 'mat:juros', 'mat:juros:1', 3, 'order', $q$Ordene as etapas para calcular o montante em juros simples$q$, $j${"items":["Identificar capital, taxa e tempo","Converter taxa e tempo para a mesma unidade","Calcular os juros com J = C · i · t","Somar os juros ao capital para obter o montante"]}$j$, $q$Primeiro os dados, depois as unidades, o cálculo dos juros e, por fim, M = C + J.$q$, 2);
select public.fj_seed_q('mat', 'mat:juros', 'mat:juros:2', 0, 'mc', $q$R$ 1.000 são aplicados a juros compostos de 10% ao ano. Qual será o montante após 2 anos?$q$, $j${"opts":["R$ 1.210","R$ 1.200","R$ 1.100","R$ 1.300"],"a":0}$j$, $q$Juros compostos: 1.000 × 1,1 × 1,1 = R$ 1.210, pois o rendimento do 1º ano também rende.$q$, 2);
select public.fj_seed_q('mat', 'mat:juros', 'mat:juros:2', 1, 'mc', $q$A dívida do cartão de crédito cresce muito rápido porque:$q$, $j${"opts":["Os juros de cada mês passam a render juros no mês seguinte","Os juros são calculados só sobre o valor inicial","A taxa diminui a cada mês","O banco cobra juros uma única vez"],"a":0}$j$, $q$O cartão usa juros compostos: a cada mês os juros entram na base de cálculo seguinte.$q$, 2);
select public.fj_seed_q('mat', 'mat:juros', 'mat:juros:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Para o mesmo capital e a mesma taxa, em prazos maiores que um período os juros compostos rendem mais que os juros simples.","a":true}$j$, $q$Verdadeiro: nos compostos os juros acumulados também rendem, acelerando o crescimento.$q$, 3);
select public.fj_seed_q('mat', 'mat:juros', 'mat:juros:2', 3, 'match', $q$Associe o termo financeiro à sua definição$q$, $j${"pairs":[["Capital","Valor inicial aplicado ou emprestado"],["Taxa de juros","Percentual cobrado por período"],["Montante","Capital somado aos juros"],["Juros compostos","Juros sobre juros a cada período"]]}$j$, $q$São os quatro termos básicos de qualquer cálculo financeiro.$q$, 1);
select public.fj_seed_q('mat', 'mat:orcamento', 'mat:orcamento:1', 0, 'mc', $q$Uma família com renda de R$ 4.000 gasta 30% com moradia. Quanto isso representa em reais?$q$, $j${"opts":["R$ 1.200","R$ 1.300","R$ 400","R$ 3.000"],"a":0}$j$, $q$30% de 4.000 é 0,30 × 4.000 = R$ 1.200.$q$, 1);
select public.fj_seed_q('mat', 'mat:orcamento', 'mat:orcamento:1', 1, 'mc', $q$Com salário de R$ 2.500, uma pessoa gasta R$ 1.000 com contas e R$ 800 com alimentação. Quanto sobra para poupar?$q$, $j${"opts":["R$ 700","R$ 500","R$ 800","R$ 1.700"],"a":0}$j$, $q$Os gastos somam 1.000 + 800 = R$ 1.800; sobra 2.500 − 1.800 = R$ 700.$q$, 2);
select public.fj_seed_q('mat', 'mat:orcamento', 'mat:orcamento:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Em um orçamento equilibrado, o total de gastos não deve ultrapassar a renda.","a":true}$j$, $q$Verdadeiro: gastar mais do que ganha gera dívidas e desequilibra o orçamento.$q$, 1);
select public.fj_seed_q('mat', 'mat:orcamento', 'mat:orcamento:1', 3, 'bank', $q$Complete a frase$q$, $j${"parts":["Quem gasta mais do que ganha fica com saldo ",", e quem gasta menos do que ganha consegue ","."],"a":["negativo","poupar"],"extra":["positivo","gastar"]}$j$, $q$Saldo negativo vira dívida; a sobra do orçamento é o que permite poupar.$q$, 1);
select public.fj_seed_q('mat', 'mat:orcamento', 'mat:orcamento:2', 0, 'mc', $q$No mercado, o arroz é vendido em pacote de 500 g por R$ 4,00 ou em pacote de 1 kg por R$ 7,00. Qual oferta vale mais a pena?$q$, $j${"opts":["O pacote de 1 kg, pois sai a R$ 7,00 o quilo","O pacote de 500 g, pois custa menos","As duas custam o mesmo por quilo","O pacote de 500 g, pois sai a R$ 7,00 o quilo"],"a":0}$j$, $q$O pacote de 500 g sai a R$ 8,00 o quilo; o de 1 kg, a R$ 7,00, é mais barato.$q$, 2);
