select public.fj_seed_q('por', 'por:classicos', 'por:classicos:1', 0, 'mc', $q$Poeta baiano conhecido como "Boca do Inferno" por suas sátiras à sociedade colonial, é o principal nome da poesia barroca no Brasil:$q$, $j${"opts":["Gregório de Matos","Tomás Antônio Gonzaga","Castro Alves","Gonçalves Dias"],"a":0}$j$, $q$Gregório de Matos satirizou a Bahia do século XVII e é o grande poeta do Barroco brasileiro.$q$, 1);
