select public.fj_seed_q('por', 'por:classicos', 'por:classicos:2', 0, 'mc', $q$Autor de "Canção do Exílio" e principal poeta da primeira geração romântica, de caráter nacionalista e indianista:$q$, $j${"opts":["Gonçalves Dias","Álvares de Azevedo","Machado de Assis","Oswald de Andrade"],"a":0}$j$, $q$Gonçalves Dias exaltou a pátria e o índio, marcas da primeira geração romântica.$q$, 1);
