select public.fj_seed_q('por', 'por:semantica', 'por:semantica:2', 1, 'mc', $q$Em "Pedro saiu cedo. Ele queria evitar o trânsito", a palavra "Ele" garante a coesão porque:$q$, $j${"opts":["Retoma 'Pedro', evitando a repetição do nome","Antecipa uma informação ainda não dita","Substitui o advérbio 'cedo'","Não se refere a nenhum termo do texto"],"a":0}$j$, $q$O pronome retoma um termo já citado: é a coesão referencial por anáfora.$q$, 2);
select public.fj_seed_q('por', 'por:semantica', 'por:semantica:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Antônimos são palavras de sentido equivalente, como belo e bonito.","a":false}$j$, $q$Falso: antônimos têm sentidos opostos; palavras de sentido semelhante são sinônimos.$q$, 1);
select public.fj_seed_q('por', 'por:semantica', 'por:semantica:2', 3, 'match', $q$Associe o recurso de coesão ou de sentido à sua definição$q$, $j${"pairs":[["Anáfora","Retomada de um termo já citado no texto"],["Catáfora","Antecipação de um termo que ainda virá"],["Sinônimo","Palavra de sentido semelhante"],["Antônimo","Palavra de sentido oposto"]]}$j$, $q$Esses recursos costuram o texto e evitam repetições desnecessárias.$q$, 3);

