-- SEÇÃO: Genética
select public.fj_seed_q('bio', 'bio:mendel', 'bio:mendel:1', 0, 'mc', $q$Segundo a primeira lei de Mendel, durante a formação dos gametas:$q$, $j${"opts":["Os dois alelos de cada característica se separam","Os alelos se fundem em um só","Cada gameta recebe os dois alelos do par","As características se misturam de forma irreversível"],"a":0}$j$, $q$Na lei da segregação, cada gameta carrega apenas um alelo de cada par.$q$, 2);
select public.fj_seed_q('bio', 'bio:mendel', 'bio:mendel:1', 1, 'mc', $q$No cruzamento entre dois heterozigotos (Aa x Aa), a proporção fenotípica esperada entre os descendentes é:$q$, $j${"opts":["3 dominantes para 1 recessivo","1 dominante para 1 recessivo","Todos dominantes","1 dominante para 3 recessivos"],"a":0}$j$, $q$Aa x Aa gera AA, Aa, Aa e aa: três com o fenótipo dominante e um com o recessivo.$q$, 2);
select public.fj_seed_q('bio', 'bio:mendel', 'bio:mendel:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Um indivíduo heterozigoto possui dois alelos diferentes para a mesma característica.","a":true}$j$, $q$Verdadeiro: heterozigoto é Aa; homozigoto tem alelos iguais, como AA ou aa.$q$, 1);
select public.fj_seed_q('bio', 'bio:mendel', 'bio:mendel:1', 3, 'match', $q$Associe o conceito de genética à sua definição$q$, $j${"pairs":[["Genótipo","Conjunto de genes do indivíduo"],["Fenótipo","Característica observável"],["Alelo dominante","Se manifesta mesmo em dose única"],["Alelo recessivo","Só se manifesta em dose dupla"]]}$j$, $q$Genótipo é a informação genética; fenótipo é o que se observa no indivíduo.$q$, 1);
select public.fj_seed_q('bio', 'bio:mendel', 'bio:mendel:2', 0, 'mc', $q$Em um heredograma, dois pais sem a característica têm um filho afetado. Isso indica que a característica é:$q$, $j${"opts":["Recessiva, e os pais são heterozigotos","Dominante","Adquirida pelo ambiente","Exclusiva do sexo masculino"],"a":0}$j$, $q$Se a característica aparece em filho de pais não afetados, ela estava escondida: é recessiva.$q$, 3);
select public.fj_seed_q('bio', 'bio:mendel', 'bio:mendel:2', 1, 'mc', $q$Um casal em que ambos têm sangue tipo O pode ter filhos de qual tipo sanguíneo?$q$, $j${"opts":["Apenas tipo O","Tipo A ou B","Apenas tipo AB","Qualquer tipo"],"a":0}$j$, $q$O tipo O é homozigoto recessivo (ii), então os filhos só podem receber alelos i.$q$, 2);
select public.fj_seed_q('bio', 'bio:mendel', 'bio:mendel:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Uma pessoa com sangue tipo AB é considerada doadora universal.","a":false}$j$, $q$Falso: o AB é o receptor universal; o doador universal é o tipo O.$q$, 2);
select public.fj_seed_q('bio', 'bio:mendel', 'bio:mendel:2', 3, 'bank', $q$Complete a frase sobre o sistema ABO$q$, $j${"parts":["No sistema ABO, o tipo "," é chamado de doador universal e o tipo "," é o receptor universal."],"a":["O","AB"],"extra":["A","B"]}$j$, $q$O tipo O não tem antígenos nas hemácias; o AB não tem anticorpos no plasma.$q$, 1);
select public.fj_seed_q('bio', 'bio:dnabiotec', 'bio:dnabiotec:1', 0, 'mc', $q$Qual base nitrogenada existe no RNA, mas não no DNA?$q$, $j${"opts":["Uracila","Timina","Adenina","Guanina"],"a":0}$j$, $q$No RNA, a uracila substitui a timina do DNA.$q$, 1);
select public.fj_seed_q('bio', 'bio:dnabiotec', 'bio:dnabiotec:1', 1, 'mc', $q$Na dupla hélice do DNA, a adenina sempre se pareia com a:$q$, $j${"opts":["Timina","Citosina","Guanina","Uracila"],"a":0}$j$, $q$O pareamento no DNA é fixo: adenina com timina e citosina com guanina.$q$, 1);
select public.fj_seed_q('bio', 'bio:dnabiotec', 'bio:dnabiotec:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"A transcrição é o processo que produz uma molécula de RNA a partir de uma fita de DNA.","a":true}$j$, $q$Verdadeiro: na transcrição o DNA serve de molde para o RNA; a tradução produz a proteína.$q$, 2);
select public.fj_seed_q('bio', 'bio:dnabiotec', 'bio:dnabiotec:1', 3, 'order', $q$Ordene as etapas da síntese de uma proteína$q$, $j${"items":["O DNA é transcrito em RNA mensageiro no núcleo","O RNA mensageiro migra para o citoplasma","O ribossomo lê os códons do RNA mensageiro","Os aminoácidos são ligados, formando a proteína"]}$j$, $q$Primeiro a transcrição no núcleo, depois a tradução nos ribossomos.$q$, 3);
select public.fj_seed_q('bio', 'bio:dnabiotec', 'bio:dnabiotec:2', 0, 'mc', $q$Um organismo transgênico é aquele que:$q$, $j${"opts":["Recebeu em seu DNA um gene de outra espécie","Sofreu apenas cruzamentos seletivos","É sempre estéril","Foi produzido por clonagem"],"a":0}$j$, $q$Transgenia é a transferência de genes entre espécies por engenharia genética.$q$, 1);
select public.fj_seed_q('bio', 'bio:dnabiotec', 'bio:dnabiotec:2', 1, 'mc', $q$A ovelha Dolly, geneticamente idêntica à ovelha que doou o núcleo da célula, foi produzida por:$q$, $j${"opts":["Clonagem","Transgenia","Fecundação in vitro","Mutação induzida"],"a":0}$j$, $q$Na clonagem, o núcleo de uma célula adulta gera um indivíduo geneticamente idêntico ao doador.$q$, 2);
select public.fj_seed_q('bio', 'bio:dnabiotec', 'bio:dnabiotec:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"A insulina usada por diabéticos pode ser produzida por bactérias que receberam o gene humano da insulina.","a":true}$j$, $q$Verdadeiro: é uma das aplicações mais conhecidas da engenharia genética.$q$, 2);
select public.fj_seed_q('bio', 'bio:dnabiotec', 'bio:dnabiotec:2', 3, 'match', $q$Associe a técnica de biotecnologia à sua descrição$q$, $j${"pairs":[["Transgenia","Inserção de gene de outra espécie"],["Clonagem","Produção de cópia geneticamente idêntica"],["Teste de DNA","Comparação de sequências genéticas"],["Terapia gênica","Correção de genes defeituosos"]]}$j$, $q$Cada técnica manipula o material genético com um objetivo diferente.$q$, 2);

-- SEÇÃO: Fisiologia humana
select public.fj_seed_q('bio', 'bio:nutricao', 'bio:nutricao:1', 0, 'mc', $q$A digestão do amido começa em qual parte do corpo?$q$, $j${"opts":["Na boca, pela ação da amilase salivar","No estômago","No intestino grosso","No esôfago"],"a":0}$j$, $q$A saliva contém amilase, enzima que já começa a quebrar o amido na boca.$q$, 1);
select public.fj_seed_q('bio', 'bio:nutricao', 'bio:nutricao:1', 1, 'mc', $q$A maior parte da absorção dos nutrientes ocorre no:$q$, $j${"opts":["Intestino delgado","Estômago","Intestino grosso","Esôfago"],"a":0}$j$, $q$As vilosidades do intestino delgado ampliam a superfície de absorção dos nutrientes.$q$, 2);
select public.fj_seed_q('bio', 'bio:nutricao', 'bio:nutricao:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"O estômago produz ácido clorídrico, que participa da digestão das proteínas.","a":true}$j$, $q$Verdadeiro: o ácido ativa a pepsina, enzima que quebra proteínas.$q$, 1);
select public.fj_seed_q('bio', 'bio:nutricao', 'bio:nutricao:1', 3, 'order', $q$Ordene o caminho do alimento no tubo digestório$q$, $j${"items":["Boca","Esôfago","Estômago","Intestino delgado"]}$j$, $q$O alimento passa pela boca e pelo esôfago, é digerido no estômago e absorvido no intestino delgado.$q$, 1);
select public.fj_seed_q('bio', 'bio:nutricao', 'bio:nutricao:2', 0, 'mc', $q$Em qual estrutura dos pulmões ocorrem as trocas gasosas com o sangue?$q$, $j${"opts":["Nos alvéolos","Na traqueia","Nos brônquios","Na laringe"],"a":0}$j$, $q$Os alvéolos são bolsinhas envolvidas por capilares, onde acontece a hematose.$q$, 1);
select public.fj_seed_q('bio', 'bio:nutricao', 'bio:nutricao:2', 1, 'mc', $q$O principal músculo responsável pelos movimentos respiratórios é o:$q$, $j${"opts":["Diafragma","Bíceps","Coração","Masseter"],"a":0}$j$, $q$A contração do diafragma aumenta o volume do tórax e faz o ar entrar.$q$, 1);
select public.fj_seed_q('bio', 'bio:nutricao', 'bio:nutricao:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Na expiração, o diafragma se contrai e o ar entra nos pulmões.","a":false}$j$, $q$Falso: o diafragma contrai na inspiração; na expiração ele relaxa e o ar sai.$q$, 2);
select public.fj_seed_q('bio', 'bio:nutricao', 'bio:nutricao:2', 3, 'bank', $q$Complete a frase sobre as trocas gasosas$q$, $j${"parts":["Nos alvéolos, o sangue recebe "," e libera ",", em um processo chamado hematose."],"a":["oxigênio","gás carbônico"],"extra":["nitrogênio","hidrogênio"]}$j$, $q$Na hematose, o oxigênio passa para o sangue e o gás carbônico é eliminado.$q$, 2);
select public.fj_seed_q('bio', 'bio:controle', 'bio:controle:1', 0, 'mc', $q$O sangue rico em oxigênio sai do coração para o corpo por qual vaso?$q$, $j${"opts":["Artéria aorta","Veia cava","Artéria pulmonar","Veia pulmonar"],"a":0}$j$, $q$A aorta é a maior artéria do corpo e distribui o sangue oxigenado do ventrículo esquerdo.$q$, 2);
select public.fj_seed_q('bio', 'bio:controle', 'bio:controle:1', 1, 'mc', $q$A unidade dos rins responsável por filtrar o sangue e formar a urina é o:$q$, $j${"opts":["Néfron","Alvéolo","Neurônio","Vilosidade"],"a":0}$j$, $q$Cada rim tem cerca de um milhão de néfrons, que filtram o sangue e produzem a urina.$q$, 2);
select public.fj_seed_q('bio', 'bio:controle', 'bio:controle:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"As veias são os vasos que levam o sangue do coração para os tecidos do corpo.","a":false}$j$, $q$Falso: quem leva o sangue do coração para o corpo são as artérias; as veias trazem de volta.$q$, 2);
select public.fj_seed_q('bio', 'bio:controle', 'bio:controle:1', 3, 'match', $q$Associe a estrutura à sua função$q$, $j${"pairs":[["Artérias","Levam sangue do coração para o corpo"],["Veias","Trazem o sangue de volta ao coração"],["Rins","Filtram o sangue e formam a urina"],["Bexiga","Armazena a urina"]]}$j$, $q$Circulação e excreção trabalham juntas para transportar e limpar o sangue.$q$, 1);
select public.fj_seed_q('bio', 'bio:controle', 'bio:controle:2', 0, 'mc', $q$Qual hormônio, produzido pelo pâncreas, reduz a taxa de glicose no sangue?$q$, $j${"opts":["Insulina","Adrenalina","Glucagon","Tiroxina"],"a":0}$j$, $q$A insulina faz a glicose entrar nas células; sua falta ou mau funcionamento causa diabetes.$q$, 2);
select public.fj_seed_q('bio', 'bio:controle', 'bio:controle:2', 1, 'mc', $q$As vacinas protegem o organismo porque:$q$, $j${"opts":["Estimulam a produção de anticorpos e células de memória","Contêm anticorpos prontos para uso imediato","Matam diretamente os microrganismos","Substituem o sistema imunológico"],"a":0}$j$, $q$A vacina apresenta o antígeno ao corpo, que aprende a se defender antes da doença real.$q$, 2);
select public.fj_seed_q('bio', 'bio:controle', 'bio:controle:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"O soro contém anticorpos prontos e é usado em emergências, como em picadas de cobra.","a":true}$j$, $q$Verdadeiro: o soro é imunização passiva, de efeito rápido; a vacina é preventiva.$q$, 2);
select public.fj_seed_q('bio', 'bio:controle', 'bio:controle:2', 3, 'order', $q$Ordene as etapas da proteção gerada por uma vacina$q$, $j${"items":["A vacina introduz o antígeno enfraquecido ou inativado","O sistema imune reconhece o antígeno","O corpo produz anticorpos e células de memória","Em novo contato com o agente, a resposta é rápida"]}$j$, $q$A vacina treina o sistema imune para responder depressa a um futuro contágio.$q$, 3);

-- SEÇÃO: Evolução e biodiversidade
select public.fj_seed_q('bio', 'bio:darwin', 'bio:darwin:1', 0, 'mc', $q$Segundo a seleção natural de Darwin, os indivíduos mais adaptados ao ambiente:$q$, $j${"opts":["Sobrevivem mais e deixam mais descendentes","Modificam o próprio corpo por esforço","Sempre são os maiores e mais fortes","Transmitem características adquiridas durante a vida"],"a":0}$j$, $q$A seleção natural favorece a reprodução de quem está mais adaptado ao ambiente.$q$, 1);
select public.fj_seed_q('bio', 'bio:darwin', 'bio:darwin:1', 1, 'mc', $q$O surgimento de bactérias resistentes a antibióticos é um exemplo de seleção natural porque:$q$, $j${"opts":["O antibiótico elimina as sensíveis e as resistentes já existentes sobrevivem","O antibiótico ensina as bactérias a resistir","As bactérias mudam de espécie ao tomar o remédio","A resistência surge por vontade das bactérias"],"a":0}$j$, $q$A variação já existe na população; o antibiótico apenas seleciona as resistentes.$q$, 3);
select public.fj_seed_q('bio', 'bio:darwin', 'bio:darwin:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Para Lamarck, características adquiridas durante a vida seriam transmitidas aos descendentes.","a":true}$j$, $q$Verdadeiro: é a lei do uso e desuso, ideia de Lamarck depois superada pela genética.$q$, 2);
select public.fj_seed_q('bio', 'bio:darwin', 'bio:darwin:1', 3, 'match', $q$Associe a evidência da evolução à sua descrição$q$, $j${"pairs":[["Fósseis","Registros de seres que viveram no passado"],["Órgãos homólogos","Mesma origem e funções diferentes"],["Órgãos vestigiais","Estruturas reduzidas, quase sem função"],["DNA comparado","Semelhança genética entre espécies"]]}$j$, $q$Diversas evidências independentes sustentam a teoria da evolução.$q$, 2);
select public.fj_seed_q('bio', 'bio:darwin', 'bio:darwin:2', 0, 'mc', $q$A especiação alopátrica acontece quando:$q$, $j${"opts":["Uma barreira geográfica separa populações da mesma espécie","Duas espécies se fundem em uma só","Um indivíduo sofre mutação e vira outra espécie","Uma população aumenta muito de tamanho"],"a":0}$j$, $q$Isoladas por uma barreira, as populações acumulam diferenças até virar espécies distintas.$q$, 2);
select public.fj_seed_q('bio', 'bio:darwin', 'bio:darwin:2', 1, 'mc', $q$Duas populações passam a ser consideradas espécies diferentes quando:$q$, $j${"opts":["Não conseguem mais cruzar gerando descendentes férteis","Vivem em cidades diferentes","Têm cores diferentes","Comem alimentos diferentes"],"a":0}$j$, $q$O critério biológico de espécie é o isolamento reprodutivo.$q$, 2);
select public.fj_seed_q('bio', 'bio:darwin', 'bio:darwin:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"O cavalo e o jumento pertencem à mesma espécie, pois geram a mula, que é fértil.","a":false}$j$, $q$Falso: a mula é estéril, o que mostra que cavalo e jumento são espécies diferentes.$q$, 3);
select public.fj_seed_q('bio', 'bio:darwin', 'bio:darwin:2', 3, 'order', $q$Ordene as etapas da formação de uma nova espécie por isolamento geográfico$q$, $j${"items":["Uma barreira geográfica separa a população","As populações isoladas acumulam diferenças genéticas","Surge o isolamento reprodutivo entre elas","Formam-se duas espécies distintas"]}$j$, $q$Separação, divergência genética e isolamento reprodutivo levam à especiação.$q$, 3);
select public.fj_seed_q('bio', 'bio:diversidade', 'bio:diversidade:1', 0, 'mc', $q$Na classificação biológica, a categoria mais específica, que agrupa indivíduos capazes de cruzar entre si, é:$q$, $j${"opts":["Espécie","Reino","Filo","Família"],"a":0}$j$, $q$A hierarquia vai do reino, o grupo mais amplo, até a espécie, o mais específico.$q$, 1);
select public.fj_seed_q('bio', 'bio:diversidade', 'bio:diversidade:1', 1, 'mc', $q$No nome científico Homo sapiens, a palavra Homo indica:$q$, $j${"opts":["O gênero","A espécie","O reino","A família"],"a":0}$j$, $q$Na nomenclatura binomial, o primeiro nome é o gênero e o conjunto dos dois indica a espécie.$q$, 2);
