select public.fj_seed_q('geo', 'geo:globalizacao', 'geo:globalizacao:2', 0, 'mc', $q$O Mercosul é um bloco econômico formado por países:$q$, $j${"opts":["Da América do Sul, como Brasil e Argentina","Da Europa Ocidental","Do Sudeste Asiático","Da América do Norte"],"a":0}$j$, $q$O Mercosul nasceu em 1991 com Brasil, Argentina, Paraguai e Uruguai.$q$, 1);
select public.fj_seed_q('geo', 'geo:globalizacao', 'geo:globalizacao:2', 1, 'mc', $q$A União Europeia é considerada o bloco mais avançado porque:$q$, $j${"opts":["Adota moeda comum e livre circulação de pessoas","Cobra tarifas máximas entre os países-membros","Proíbe o comércio entre os integrantes","Reúne somente dois países"],"a":0}$j$, $q$O euro e a livre circulação de pessoas, bens e capitais marcam o estágio de união econômica e monetária.$q$, 2);
select public.fj_seed_q('geo', 'geo:globalizacao', 'geo:globalizacao:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Em uma zona de livre comércio, os países reduzem ou eliminam tarifas alfandegárias entre si.","a":true}$j$, $q$Verdadeiro: a zona de livre comércio é o primeiro nível de integração entre países.$q$, 2);
select public.fj_seed_q('geo', 'geo:globalizacao', 'geo:globalizacao:2', 3, 'bank', $q$Complete a frase$q$, $j${"parts":["O "," reúne Brasil, Argentina, Paraguai e Uruguai, enquanto a "," adota o euro como moeda comum."],"a":["Mercosul","União Europeia"],"extra":["Nafta","Opep"]}$j$, $q$Mercosul: bloco sul-americano. União Europeia: bloco com moeda única, o euro.$q$, 1);
select public.fj_seed_q('geo', 'geo:ordemmundial', 'geo:ordemmundial:1', 0, 'mc', $q$Refugiados são pessoas que:$q$, $j${"opts":["Deixam seu país fugindo de guerra, perseguição ou violência","Viajam a turismo para outros países","Migram apenas em busca de salários maiores","Mudam de cidade dentro do próprio país"],"a":0}$j$, $q$O refúgio é um direito reconhecido a quem foge de perseguições e conflitos, segundo a ONU.$q$, 1);
select public.fj_seed_q('geo', 'geo:ordemmundial', 'geo:ordemmundial:1', 1, 'mc', $q$Durante a Guerra Fria, a ordem mundial era chamada de bipolar porque:$q$, $j${"opts":["EUA e URSS disputavam a hegemonia global","Todos os países eram neutros","A China dominava os dois blocos","A Europa estava politicamente unificada"],"a":0}$j$, $q$O mundo se dividiu entre o bloco capitalista, liderado pelos EUA, e o socialista, liderado pela URSS.$q$, 2);
select public.fj_seed_q('geo', 'geo:ordemmundial', 'geo:ordemmundial:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Após o fim da Guerra Fria, consolidou-se uma ordem multipolar, com vários centros de poder econômico.","a":true}$j$, $q$Verdadeiro: EUA, União Europeia, China e Japão passaram a dividir o poder econômico mundial.$q$, 3);
select public.fj_seed_q('geo', 'geo:ordemmundial', 'geo:ordemmundial:1', 3, 'order', $q$Ordene os acontecimentos do mais antigo para o mais recente$q$, $j${"items":["Fim da Segunda Guerra Mundial","Guerra Fria entre EUA e URSS","Queda do Muro de Berlim","Ordem multipolar atual"]}$j$, $q$A Guerra Fria começou após 1945 e terminou com a queda do Muro em 1989, abrindo a ordem multipolar.$q$, 2);
select public.fj_seed_q('geo', 'geo:ordemmundial', 'geo:ordemmundial:2', 0, 'mc', $q$O grupo BRICS foi formado originalmente por:$q$, $j${"opts":["Brasil, Rússia, Índia, China e África do Sul","Bélgica, Romênia, Itália, Chile e Suécia","Apenas países da Europa Ocidental","Os países mais ricos do G7"],"a":0}$j$, $q$O BRICS reúne grandes países emergentes que buscam mais peso nas decisões globais.$q$, 1);
select public.fj_seed_q('geo', 'geo:ordemmundial', 'geo:ordemmundial:2', 1, 'mc', $q$O principal objetivo da ONU, criada em 1945, é:$q$, $j${"opts":["Manter a paz e a segurança internacionais","Controlar o preço mundial do petróleo","Administrar a internet global","Organizar competições esportivas"],"a":0}$j$, $q$A ONU nasceu após a Segunda Guerra para evitar novos conflitos e promover a cooperação.$q$, 1);
select public.fj_seed_q('geo', 'geo:ordemmundial', 'geo:ordemmundial:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"A OMC é o organismo internacional que estabelece as regras do comércio entre os países.","a":true}$j$, $q$Verdadeiro: a Organização Mundial do Comércio regula e arbitra disputas comerciais.$q$, 2);
select public.fj_seed_q('geo', 'geo:ordemmundial', 'geo:ordemmundial:2', 3, 'match', $q$Associe o organismo internacional à sua função$q$, $j${"pairs":[["ONU","Paz e segurança internacionais"],["OMC","Regras do comércio mundial"],["FMI","Empréstimos e estabilidade financeira"],["OMS","Saúde pública global"]]}$j$, $q$Cada organismo internacional cuida de uma área da cooperação entre os países.$q$, 2);

