select public.fj_seed_q('geo', 'geo:aquecimento', 'geo:aquecimento:2', 0, 'mc', $q$Uma das principais causas do desmatamento na Amazônia é:$q$, $j${"opts":["A expansão da pecuária e da agricultura","O excesso de chuvas na região","O turismo ecológico","A criação de parques nacionais"],"a":0}$j$, $q$A abertura de pastos e lavouras é o principal motor da derrubada da floresta.$q$, 1);
select public.fj_seed_q('geo', 'geo:aquecimento', 'geo:aquecimento:2', 1, 'mc', $q$Uma consequência do desmatamento da Amazônia para o clima do continente é:$q$, $j${"opts":["A redução da umidade transportada pelos chamados rios voadores","O aumento imediato das chuvas no Sudeste","O fim definitivo das queimadas","O resfriamento global instantâneo"],"a":0}$j$, $q$A floresta bombeia vapor de água que leva chuva a outras regiões; sem ela, chove menos.$q$, 3);
select public.fj_seed_q('geo', 'geo:aquecimento', 'geo:aquecimento:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"As queimadas liberam gás carbônico e agravam o aquecimento global.","a":true}$j$, $q$Verdadeiro: ao queimar, a vegetação devolve à atmosfera o carbono que havia armazenado.$q$, 1);
select public.fj_seed_q('geo', 'geo:aquecimento', 'geo:aquecimento:2', 3, 'order', $q$Ordene as etapas típicas do avanço do desmatamento na floresta$q$, $j${"items":["Abertura de estradas na mata","Extração ilegal de madeira","Queimada para limpar o terreno","Ocupação com pasto ou lavoura"]}$j$, $q$O desmatamento costuma seguir esse ciclo: estrada, madeira, fogo e, por fim, pasto ou lavoura.$q$, 3);
