select public.fj_seed_q('geo', 'geo:recursos', 'geo:recursos:1', 1, 'mc', $q$No Brasil, o setor que mais consome água é:$q$, $j${"opts":["A agricultura, por causa da irrigação","O consumo doméstico das famílias","A mineração","O setor de serviços"],"a":0}$j$, $q$A irrigação agrícola responde pela maior parte da retirada de água no país.$q$, 2);
select public.fj_seed_q('geo', 'geo:recursos', 'geo:recursos:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"O Aquífero Guarani é uma das maiores reservas subterrâneas de água doce do mundo.","a":true}$j$, $q$Verdadeiro: ele se estende pelo Brasil, Argentina, Paraguai e Uruguai.$q$, 2);
select public.fj_seed_q('geo', 'geo:recursos', 'geo:recursos:1', 3, 'match', $q$Associe o conceito à definição$q$, $j${"pairs":[["Aquífero","Reserva de água no subsolo"],["Bacia hidrográfica","Área drenada por um rio principal e seus afluentes"],["Assoreamento","Acúmulo de sedimentos no leito do rio"],["Crise hídrica","Escassez de água para abastecimento"]]}$j$, $q$Conceitos básicos para entender os recursos hídricos.$q$, 2);
select public.fj_seed_q('geo', 'geo:recursos', 'geo:recursos:2', 0, 'mc', $q$A política dos 3 R da sustentabilidade corresponde a:$q$, $j${"opts":["Reduzir, reutilizar e reciclar","Reclamar, revender e recolher","Reflorestar, regar e remover","Reformar, repor e revisar"],"a":0}$j$, $q$Primeiro consumir menos, depois reaproveitar e, por fim, reciclar os materiais.$q$, 1);
select public.fj_seed_q('geo', 'geo:recursos', 'geo:recursos:2', 1, 'mc', $q$A obsolescência programada contribui para o aumento do lixo porque:$q$, $j${"opts":["Os produtos são projetados para durar pouco e ser trocados logo","Os produtos duram tempo demais","As pessoas passam a consumir cada vez menos","As fábricas deixam de produzir embalagens"],"a":0}$j$, $q$Produtos feitos para durar pouco aceleram o descarte e o consumo de novos itens.$q$, 2);
