select public.fj_seed_q('geo', 'geo:atmosfera', 'geo:atmosfera:1', 0, 'mc', $q$A altitude influencia o clima porque:$q$, $j${"opts":["Quanto mais alto o lugar, menor a temperatura média","Quanto mais alto o lugar, mais quente ele fica","A altitude não interfere na temperatura","Lugares altos recebem mais calor do solo"],"a":0}$j$, $q$O ar fica mais rarefeito com a altitude e retém menos calor, por isso montanhas são frias.$q$, 1);
select public.fj_seed_q('geo', 'geo:atmosfera', 'geo:atmosfera:1', 1, 'mc', $q$As frentes frias que atingem o Sul e o Sudeste do Brasil resultam do avanço:$q$, $j${"opts":["Da massa polar atlântica","Da massa equatorial continental","Exclusivamente do fenômeno El Niño","Dos ventos alísios do Nordeste"],"a":0}$j$, $q$A massa polar atlântica, fria e úmida, avança do sul e provoca quedas de temperatura e chuvas.$q$, 3);
select public.fj_seed_q('geo', 'geo:atmosfera', 'geo:atmosfera:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"A maritimidade faz cidades litorâneas terem menor variação de temperatura que cidades do interior.","a":true}$j$, $q$Verdadeiro: o mar esquenta e esfria devagar, amenizando a amplitude térmica no litoral.$q$, 2);
