(md5('lic:fis:optica:2')::uuid, md5('uni:fis:optica')::uuid, 'Luz e cores', 'A camiseta azul, o arco-íris e o espectro.', 1),
(md5('lic:fis:energia:1')::uuid, md5('uni:fis:energia')::uuid, 'Fontes de energia', 'Renováveis, não renováveis e a matriz brasileira.', 0),
(md5('lic:fis:energia:2')::uuid, md5('uni:fis:energia')::uuid, 'Energia no cotidiano', 'Chuveiro, stand-by e transformações de energia.', 1),
(md5('lic:fis:quantica:1')::uuid, md5('uni:fis:quantica')::uuid, 'Efeito fotoelétrico e radiações', 'Da célula solar ao protetor solar.', 0),
(md5('lic:fis:quantica:2')::uuid, md5('uni:fis:quantica')::uuid, 'Física nuclear básica', 'Fissão, fusão e meia-vida.', 1)
on conflict (id) do nothing;

-- SEÇÃO: Termologia
select public.fj_seed_q('fis', 'fis:temperatura', 'fis:temperatura:1', 0, 'mc', $q$No dia a dia dizemos que algo está 'quente' ou 'frio'. Fisicamente, a temperatura mede:$q$, $j${"opts":["O grau de agitação das partículas do corpo","A quantidade de calor armazenada no corpo","O peso das moléculas do corpo","A umidade do ar ao redor do corpo"],"a":0}$j$, $q$Temperatura é a medida da agitação (energia cinética média) das partículas da matéria.$q$, 1);
select public.fj_seed_q('fis', 'fis:temperatura', 'fis:temperatura:1', 1, 'mc', $q$Um termômetro marca 25 °C na praia. Na escala Fahrenheit, essa temperatura vale:$q$, $j${"opts":["77 °F","57 °F","45 °F","25 °F"],"a":0}$j$, $q$F = 1,8 × C + 32, então 1,8 × 25 + 32 = 45 + 32 = 77 °F.$q$, 2);
select public.fj_seed_q('fis', 'fis:temperatura', 'fis:temperatura:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Dois corpos em contato por bastante tempo tendem a atingir a mesma temperatura, o chamado equilíbrio térmico.","a":true}$j$, $q$Verdadeiro: o calor flui do corpo mais quente para o mais frio até as temperaturas se igualarem.$q$, 1);
select public.fj_seed_q('fis', 'fis:temperatura', 'fis:temperatura:1', 3, 'match', $q$Associe cada escala ou marco à sua característica$q$, $j${"pairs":[["Celsius","Água congela a 0 graus"],["Fahrenheit","Água congela a 32 graus"],["Kelvin","Escala absoluta do SI"],["Zero absoluto","Equivale a -273 °C"]]}$j$, $q$Cada escala usa pontos fixos diferentes; o Kelvin começa no zero absoluto.$q$, 2);
select public.fj_seed_q('fis', 'fis:temperatura', 'fis:temperatura:2', 0, 'mc', $q$Em um experimento, um gás está a 300 K. Essa temperatura, em graus Celsius, é:$q$, $j${"opts":["27 °C","300 °C","73 °C","573 °C"],"a":0}$j$, $q$C = K - 273, logo 300 - 273 = 27 °C.$q$, 2);
select public.fj_seed_q('fis', 'fis:temperatura', 'fis:temperatura:2', 1, 'mc', $q$Uma pessoa com febre de 40 °C tem, na escala Kelvin, temperatura de:$q$, $j${"opts":["313 K","233 K","413 K","40 K"],"a":0}$j$, $q$K = C + 273, logo 40 + 273 = 313 K.$q$, 2);
select public.fj_seed_q('fis', 'fis:temperatura', 'fis:temperatura:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"A escala Fahrenheit é a unidade oficial de temperatura do Sistema Internacional (SI).","a":false}$j$, $q$Falso: a unidade do SI é o kelvin (K); o Fahrenheit é usado em países como os Estados Unidos.$q$, 2);
select public.fj_seed_q('fis', 'fis:temperatura', 'fis:temperatura:2', 3, 'order', $q$Ordene as temperaturas da mais fria para a mais quente$q$, $j${"items":["0 K (zero absoluto)","0 °F","0 °C","300 K"]}$j$, $q$0 K = -273 °C, 0 °F é cerca de -18 °C, depois vem 0 °C e, por fim, 300 K = 27 °C.$q$, 3);
select public.fj_seed_q('fis', 'fis:calor', 'fis:calor:1', 0, 'mc', $q$Em Física, calor é definido como:$q$, $j${"opts":["Energia térmica em trânsito entre corpos de temperaturas diferentes","A temperatura de um corpo muito aquecido","Uma substância que passa de um corpo a outro","O mesmo que sensação térmica"],"a":0}$j$, $q$Calor é energia que flui espontaneamente do corpo mais quente para o mais frio.$q$, 1);
select public.fj_seed_q('fis', 'fis:calor', 'fis:calor:1', 1, 'mc', $q$Para aquecer 200 g de água de 20 °C até 70 °C (c = 1 cal/g°C), a energia necessária é:$q$, $j${"opts":["10.000 cal","200 cal","1.000 cal","14.000 cal"],"a":0}$j$, $q$Q = m·c·ΔT = 200 × 1 × 50 = 10.000 cal.$q$, 2);
select public.fj_seed_q('fis', 'fis:calor', 'fis:calor:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"O calor flui espontaneamente do corpo mais quente para o mais frio, nunca o contrário.","a":true}$j$, $q$Verdadeiro: esse é o sentido espontâneo da transferência de calor.$q$, 1);
select public.fj_seed_q('fis', 'fis:calor', 'fis:calor:1', 3, 'bank', $q$Complete a frase sobre um dia de praia$q$, $j${"parts":["A areia esquenta rápido porque tem "," calor específico; já o mar demora para aquecer, pois a água tem "," calor específico."],"a":["baixo","alto"],"extra":["nenhum","o mesmo"]}$j$, $q$Quanto menor o calor específico, mais rápido o material muda de temperatura.$q$, 2);
select public.fj_seed_q('fis', 'fis:calor', 'fis:calor:2', 0, 'mc', $q$A roupa no varal seca porque a água passa do estado líquido para o gasoso. Esse processo chama-se:$q$, $j${"opts":["Vaporização","Condensação","Fusão","Sublimação"],"a":0}$j$, $q$A passagem de líquido para gás é a vaporização (no varal, por evaporação).$q$, 1);
select public.fj_seed_q('fis', 'fis:calor', 'fis:calor:2', 1, 'mc', $q$Os trilhos de trem são instalados com pequenas folgas entre as barras para:$q$, $j${"opts":["Permitir a dilatação térmica nos dias quentes","Economizar material na construção","Reduzir o atrito com as rodas do trem","Evitar a ferrugem do metal"],"a":0}$j$, $q$Com o calor o metal se dilata; sem a folga, os trilhos entortariam.$q$, 2);
select public.fj_seed_q('fis', 'fis:calor', 'fis:calor:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Na panela de pressão, a água ferve acima de 100 °C porque a pressão interna é maior que a atmosférica.","a":true}$j$, $q$Verdadeiro: pressão maior eleva o ponto de ebulição, e o alimento cozinha mais rápido.$q$, 2);
select public.fj_seed_q('fis', 'fis:calor', 'fis:calor:2', 3, 'match', $q$Associe cada mudança de estado à sua definição$q$, $j${"pairs":[["Fusão","Sólido vira líquido"],["Vaporização","Líquido vira gás"],["Condensação","Gás vira líquido"],["Solidificação","Líquido vira sólido"]]}$j$, $q$São as principais mudanças de estado físico da matéria.$q$, 1);

-- SEÇÃO: Ondas e óptica
select public.fj_seed_q('fis', 'fis:ondassom', 'fis:ondassom:1', 0, 'mc', $q$Uma boia no mar oscila com ondas de frequência 2 Hz e comprimento de onda 3 m. A velocidade dessas ondas é:$q$, $j${"opts":["6 m/s","1,5 m/s","5 m/s","0,7 m/s"],"a":0}$j$, $q$v = λ × f = 3 × 2 = 6 m/s.$q$, 2);
select public.fj_seed_q('fis', 'fis:ondassom', 'fis:ondassom:1', 1, 'mc', $q$O que diferencia um som agudo de um som grave é a:$q$, $j${"opts":["Frequência da onda sonora","Intensidade (volume) do som","Velocidade de propagação no ar","Temperatura da fonte sonora"],"a":0}$j$, $q$Sons agudos têm alta frequência e graves têm baixa; o volume depende da amplitude.$q$, 1);
select public.fj_seed_q('fis', 'fis:ondassom', 'fis:ondassom:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Astronautas não ouvem explosões no espaço porque o som não se propaga no vácuo.","a":true}$j$, $q$Verdadeiro: o som é onda mecânica e precisa de um meio material para se propagar.$q$, 1);
select public.fj_seed_q('fis', 'fis:ondassom', 'fis:ondassom:1', 3, 'bank', $q$Complete a frase sobre as ondas$q$, $j${"parts":["A "," é o número de oscilações por segundo, medida em hertz, e a "," está ligada à energia e ao volume do som."],"a":["frequência","amplitude"],"extra":["velocidade","densidade"]}$j$, $q$Frequência: oscilações por segundo; amplitude: tamanho da oscilação, ligado à energia.$q$, 2);
select public.fj_seed_q('fis', 'fis:ondassom', 'fis:ondassom:2', 0, 'mc', $q$Ao gritar diante de um paredão de pedra, ouvimos o eco. Ele é causado pela:$q$, $j${"opts":["Reflexão do som","Refração do som","Dispersão do som","Polarização do som"],"a":0}$j$, $q$O eco é o som refletido no obstáculo que volta aos nossos ouvidos.$q$, 1);
select public.fj_seed_q('fis', 'fis:ondassom', 'fis:ondassom:2', 1, 'mc', $q$Quando uma ambulância se aproxima, a sirene parece mais aguda; ao se afastar, mais grave. Esse fenômeno é o:$q$, $j${"opts":["Efeito Doppler","Eco","Efeito estufa","Efeito fotoelétrico"],"a":0}$j$, $q$No efeito Doppler, o movimento relativo entre fonte e ouvinte altera a frequência percebida.$q$, 2);
select public.fj_seed_q('fis', 'fis:ondassom', 'fis:ondassom:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Conseguimos ouvir alguém falando do outro lado de um muro graças à difração, que faz o som contornar obstáculos.","a":true}$j$, $q$Verdadeiro: o som tem grande comprimento de onda e contorna obstáculos com facilidade.$q$, 3);
select public.fj_seed_q('fis', 'fis:ondassom', 'fis:ondassom:2', 3, 'match', $q$Associe o fenômeno ondulatório ao exemplo$q$, $j${"pairs":[["Reflexão","Eco em um vale"],["Refração","Onda muda de velocidade ao trocar de meio"],["Difração","Som que contorna um muro"],["Interferência","Duas ondas que se somam ou se cancelam"]]}$j$, $q$Cada fenômeno descreve um comportamento típico das ondas.$q$, 2);
select public.fj_seed_q('fis', 'fis:optica', 'fis:optica:1', 0, 'mc', $q$Os retrovisores de motos e os espelhos de segurança de lojas são convexos porque:$q$, $j${"opts":["Ampliam o campo de visão","Aumentam o tamanho da imagem","Invertem a imagem de cabeça para baixo","Aproximam os objetos distantes"],"a":0}$j$, $q$O espelho convexo forma imagens menores, o que permite enxergar uma área maior.$q$, 2);
select public.fj_seed_q('fis', 'fis:optica', 'fis:optica:1', 1, 'mc', $q$Uma pessoa míope enxerga mal de longe. Para corrigir a miopia, usa-se lente:$q$, $j${"opts":["Divergente","Convergente","Espelhada","De aumento"],"a":0}$j$, $q$A lente divergente afasta o foco e leva a imagem de volta para a retina.$q$, 2);
select public.fj_seed_q('fis', 'fis:optica', 'fis:optica:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"No espelho plano do banheiro, a imagem formada tem o mesmo tamanho do objeto.","a":true}$j$, $q$Verdadeiro: o espelho plano forma imagem virtual, direita e do mesmo tamanho.$q$, 1);
select public.fj_seed_q('fis', 'fis:optica', 'fis:optica:1', 3, 'bank', $q$Complete a frase sobre os óculos$q$, $j${"parts":["A lente "," corrige a miopia, e a lente "," corrige a hipermetropia."],"a":["divergente","convergente"],"extra":["plana","opaca"]}$j$, $q$Miopia se corrige com lente divergente; hipermetropia, com convergente.$q$, 2);
select public.fj_seed_q('fis', 'fis:optica', 'fis:optica:2', 0, 'mc', $q$Uma camiseta vista como azul sob a luz do Sol tem essa cor porque:$q$, $j${"opts":["Reflete a luz azul e absorve as demais cores","Absorve apenas a luz azul","Emite luz própria de cor azul","Reflete todas as cores da luz"],"a":0}$j$, $q$A cor de um objeto é a cor da luz que ele reflete até os nossos olhos.$q$, 2);
select public.fj_seed_q('fis', 'fis:optica', 'fis:optica:2', 1, 'mc', $q$O arco-íris surge quando a luz do Sol atravessa gotas de chuva e se separa em várias cores. Esse fenômeno é a:$q$, $j${"opts":["Dispersão da luz","Reflexão total","Formação de sombra","Fosforescência"],"a":0}$j$, $q$Na dispersão, a luz branca se separa nas cores do espectro ao ser refratada nas gotas.$q$, 1);
select public.fj_seed_q('fis', 'fis:optica', 'fis:optica:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"A luz branca do Sol é uma cor pura, impossível de ser separada em outras cores.","a":false}$j$, $q$Falso: a luz branca é a mistura de todas as cores, como mostra o prisma de Newton.$q$, 2);
select public.fj_seed_q('fis', 'fis:optica', 'fis:optica:2', 3, 'order', $q$Ordene as ondas eletromagnéticas da menor para a maior frequência$q$, $j${"items":["Ondas de rádio","Micro-ondas","Luz visível","Raios X"]}$j$, $q$No espectro eletromagnético, a frequência cresce das ondas de rádio até os raios X e gama.$q$, 3);

-- SEÇÃO: Física moderna e energia
select public.fj_seed_q('fis', 'fis:energia', 'fis:energia:1', 0, 'mc', $q$A maior parte da eletricidade gerada no Brasil vem de:$q$, $j${"opts":["Usinas hidrelétricas","Usinas nucleares","Queima de carvão mineral","Energia geotérmica"],"a":0}$j$, $q$A matriz elétrica brasileira é dominada pelas hidrelétricas, que usam a força da água dos rios.$q$, 1);
select public.fj_seed_q('fis', 'fis:energia', 'fis:energia:1', 1, 'mc', $q$Entre as fontes de energia abaixo, a NÃO renovável é:$q$, $j${"opts":["Petróleo","Energia solar","Energia eólica","Biomassa da cana"],"a":0}$j$, $q$O petróleo leva milhões de anos para se formar e se esgota com o uso.$q$, 1);
select public.fj_seed_q('fis', 'fis:energia', 'fis:energia:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"A energia eólica é gerada a partir da força dos ventos e não emite poluentes durante a operação.","a":true}$j$, $q$Verdadeiro: os aerogeradores convertem o movimento do vento em eletricidade de forma limpa.$q$, 1);
select public.fj_seed_q('fis', 'fis:energia', 'fis:energia:1', 3, 'match', $q$Associe a fonte de energia à sua origem$q$, $j${"pairs":[["Hidrelétrica","Força da água dos rios"],["Eólica","Força dos ventos"],["Solar fotovoltaica","Luz do Sol"],["Termelétrica","Queima de combustíveis"]]}$j$, $q$Cada tipo de usina converte uma forma diferente de energia em eletricidade.$q$, 1);
select public.fj_seed_q('fis', 'fis:energia', 'fis:energia:2', 0, 'mc', $q$Um chuveiro de 5.500 W (5,5 kW) é usado meia hora por dia. Em 30 dias, o consumo de energia é de:$q$, $j${"opts":["82,5 kWh","165 kWh","5,5 kWh","2.750 kWh"],"a":0}$j$, $q$E = 5,5 kW × 0,5 h × 30 dias = 82,5 kWh.$q$, 3);
select public.fj_seed_q('fis', 'fis:energia', 'fis:energia:2', 1, 'mc', $q$No chuveiro elétrico, a principal transformação de energia é de:$q$, $j${"opts":["Elétrica em térmica","Térmica em elétrica","Química em elétrica","Elétrica em sonora"],"a":0}$j$, $q$A resistência do chuveiro converte energia elétrica em calor para aquecer a água.$q$, 1);
select public.fj_seed_q('fis', 'fis:energia', 'fis:energia:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Aparelhos em modo de espera (stand-by) não consomem energia elétrica.","a":false}$j$, $q$Falso: no stand-by ainda há consumo; por isso vale tirar da tomada o que não está em uso.$q$, 2);
select public.fj_seed_q('fis', 'fis:energia', 'fis:energia:2', 3, 'bank', $q$Complete a frase sobre o painel solar$q$, $j${"parts":["O painel solar fotovoltaico transforma energia "," diretamente em energia ","."],"a":["luminosa","elétrica"],"extra":["sonora","nuclear"]}$j$, $q$As células fotovoltaicas convertem a luz do Sol em eletricidade.$q$, 1);
select public.fj_seed_q('fis', 'fis:quantica', 'fis:quantica:1', 0, 'mc', $q$No efeito fotoelétrico, explicado por Einstein, a luz que incide sobre um metal pode:$q$, $j${"opts":["Arrancar elétrons da superfície do metal","Derreter o metal instantaneamente","Transformar o metal em um ímã","Criar prótons dentro do metal"],"a":0}$j$, $q$Fótons com energia suficiente ejetam elétrons; é a base das células fotovoltaicas.$q$, 2);
select public.fj_seed_q('fis', 'fis:quantica', 'fis:quantica:1', 1, 'mc', $q$A radiação usada para enxergar os ossos em exames de imagem é:$q$, $j${"opts":["Raios X","Ondas de rádio","Infravermelho","Luz visível"],"a":0}$j$, $q$Os raios X atravessam os tecidos moles, mas são barrados pelos ossos.$q$, 1);
select public.fj_seed_q('fis', 'fis:quantica', 'fis:quantica:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"O protetor solar ajuda a bloquear a radiação ultravioleta, que pode causar queimaduras e câncer de pele.","a":true}$j$, $q$Verdadeiro: a radiação UV é energética o bastante para danificar as células da pele.$q$, 1);
select public.fj_seed_q('fis', 'fis:quantica', 'fis:quantica:1', 3, 'order', $q$Ordene as radiações da menos energética para a mais energética$q$, $j${"items":["Ondas de rádio","Infravermelho","Ultravioleta","Raios gama"]}$j$, $q$A energia da radiação cresce com a frequência, do rádio até os raios gama.$q$, 2);
select public.fj_seed_q('fis', 'fis:quantica', 'fis:quantica:2', 0, 'mc', $q$As usinas nucleares brasileiras, como Angra 1 e Angra 2, geram energia a partir da:$q$, $j${"opts":["Fissão de núcleos de urânio","Fusão de núcleos de hidrogênio","Queima do urânio com oxigênio","Dilatação térmica do urânio"],"a":0}$j$, $q$Na fissão, núcleos pesados se dividem e liberam uma enorme quantidade de energia.$q$, 2);
select public.fj_seed_q('fis', 'fis:quantica', 'fis:quantica:2', 1, 'mc', $q$A energia do Sol, que chega à Terra como luz e calor, é produzida por:$q$, $j${"opts":["Fusão nuclear de hidrogênio em hélio","Fissão de núcleos de urânio","Combustão de gases na superfície","Atrito entre as camadas solares"],"a":0}$j$, $q$No núcleo do Sol, núcleos de hidrogênio se fundem formando hélio e liberando energia.$q$, 2);
select public.fj_seed_q('fis', 'fis:quantica', 'fis:quantica:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"A fusão nuclear é o processo em que um núcleo pesado, como o do urânio, se divide em núcleos menores.","a":false}$j$, $q$Falso: isso é a fissão; na fusão, núcleos leves se unem formando um núcleo maior.$q$, 3);
select public.fj_seed_q('fis', 'fis:quantica', 'fis:quantica:2', 3, 'match', $q$Associe o conceito nuclear à sua descrição$q$, $j${"pairs":[["Fissão","Núcleo pesado se divide"],["Fusão","Núcleos leves se unem"],["Meia-vida","Tempo para metade da amostra decair"],["Radioterapia","Radiação usada contra tumores"]]}$j$, $q$Conceitos básicos da física nuclear e uma de suas aplicações médicas.$q$, 2);

