-- SEÇÃO: Argumentação
select public.fj_seed_q('red', 'red:argumentos', 'red:argumentos:1', 0, 'mc', $q$Em uma redação do ENEM, citar uma pesquisa do IBGE para sustentar a tese é um exemplo de argumento por:$q$, $j${"opts":["Comprovação com dados estatísticos","Apelo à emoção do leitor","Narração de experiência pessoal","Repetição da tese com outras palavras"],"a":0}$j$, $q$Dados de instituições confiáveis dão base objetiva e verificável ao argumento.$q$, 1);
select public.fj_seed_q('red', 'red:argumentos', 'red:argumentos:1', 1, 'mc', $q$O chamado argumento de autoridade consiste em:$q$, $j${"opts":["Citar um especialista ou pensador reconhecido para apoiar a tese","Impor a opinião com frases de ordem","Usar a própria experiência como prova definitiva","Apresentar a opinião da maioria como verdade"],"a":0}$j$, $q$A credibilidade de quem é referência no assunto empresta força à tese do autor.$q$, 2);
select public.fj_seed_q('red', 'red:argumentos', 'red:argumentos:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Um exemplo isolado, sozinho, é suficiente para comprovar uma tese em um texto dissertativo.","a":false}$j$, $q$Falso: o exemplo ilustra a ideia, mas precisa vir acompanhado de dados ou raciocínios que a sustentem.$q$, 2);
select public.fj_seed_q('red', 'red:argumentos', 'red:argumentos:1', 3, 'match', $q$Associe o tipo de argumento ao seu exemplo$q$, $j${"pairs":[["Dados","Segundo o IBGE, 11% dos jovens não estudam nem trabalham"],["Autoridade","Como afirma o sociólogo Zygmunt Bauman"],["Exemplo","O caso de uma escola pública premiada em robótica"],["Causa e consequência","A evasão escolar reduz a renda futura do estudante"]]}$j$, $q$Cada estratégia sustenta a tese por um caminho diferente: números, vozes de referência, casos concretos ou relações lógicas.$q$, 2);
select public.fj_seed_q('red', 'red:argumentos', 'red:argumentos:2', 0, 'mc', $q$A frase 'a falta de saneamento provoca doenças, o que sobrecarrega os hospitais' usa qual estratégia argumentativa?$q$, $j${"opts":["Relação de causa e consequência","Argumento de autoridade","Ironia","Comparação histórica"],"a":0}$j$, $q$A frase encadeia um fato à sua consequência, mostrando o efeito do problema.$q$, 1);
select public.fj_seed_q('red', 'red:argumentos', 'red:argumentos:2', 1, 'mc', $q$Concluir que 'todo jovem é desinteressado' a partir de dois casos observados é a falácia da:$q$, $j${"opts":["Generalização apressada","Falsa autoridade","Petição de princípio","Falsa analogia"],"a":0}$j$, $q$Poucos casos não bastam para afirmar algo sobre um grupo inteiro.$q$, 3);
select public.fj_seed_q('red', 'red:argumentos', 'red:argumentos:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Atacar quem fala, em vez de rebater o que foi dito, é a falácia conhecida como ad hominem.","a":true}$j$, $q$Verdadeiro: desqualificar a pessoa não refuta o argumento dela.$q$, 2);
select public.fj_seed_q('red', 'red:argumentos', 'red:argumentos:2', 3, 'bank', $q$Complete a frase sobre falácias$q$, $j${"parts":["Na falácia do "," a fala do adversário é distorcida para ser derrubada com facilidade; já no falso "," dois fatos que apenas coincidem são tratados como causa e efeito."],"a":["espantalho","nexo causal"],"extra":["silogismo","dilema"]}$j$, $q$Espantalho: distorce o oponente. Falso nexo causal: confunde coincidência com causa.$q$, 3);
select public.fj_seed_q('red', 'red:tese', 'red:tese:1', 0, 'mc', $q$Na redação do ENEM, a tese é:$q$, $j${"opts":["O ponto de vista que o autor defende sobre o tema","Um resumo imparcial do tema","Uma pergunta deixada sem resposta","A citação que abre o texto"],"a":0}$j$, $q$A tese é a opinião defendida: todo o texto existe para sustentá-la.$q$, 1);
select public.fj_seed_q('red', 'red:tese', 'red:tese:1', 1, 'mc', $q$O projeto de texto, valorizado na competência 3 do ENEM, consiste em:$q$, $j${"opts":["Planejar quais argumentos usar e em que ordem, a serviço da tese","Decorar um modelo pronto de redação","Escrever primeiro e organizar depois","Reunir o máximo de dados possível, mesmo soltos"],"a":0}$j$, $q$Um bom projeto organiza as ideias com progressão e direção, sempre defendendo a tese.$q$, 2);
select public.fj_seed_q('red', 'red:tese', 'red:tese:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Na estrutura clássica do dissertativo-argumentativo, a tese já aparece na introdução.","a":true}$j$, $q$Verdadeiro: anunciar a tese cedo orienta o leitor e organiza o restante do texto.$q$, 1);
select public.fj_seed_q('red', 'red:tese', 'red:tese:1', 3, 'order', $q$Ordene as etapas de um bom projeto de texto$q$, $j${"items":["Compreender o tema e seu recorte","Definir a tese","Escolher os argumentos e o repertório","Planejar a proposta de intervenção"]}$j$, $q$Primeiro entende-se o tema; só então se define a tese, os argumentos e, por fim, a solução.$q$, 2);
select public.fj_seed_q('red', 'red:tese', 'red:tese:2', 0, 'mc', $q$Contra-argumentar, em um texto dissertativo, significa:$q$, $j${"opts":["Apresentar a visão oposta e refutá-la com novos argumentos","Concordar com todas as opiniões em jogo","Mudar de tese no meio do texto","Ignorar as opiniões diferentes da sua"],"a":0}$j$, $q$Quem antecipa e rebate a objeção mostra domínio do debate e fortalece a própria tese.$q$, 2);
select public.fj_seed_q('red', 'red:tese', 'red:tese:2', 1, 'mc', $q$Qual conectivo é típico para introduzir uma concessão antes da refutação?$q$, $j${"opts":["Embora","Portanto","Ou seja","Além disso"],"a":0}$j$, $q$O 'embora' admite parcialmente a ideia contrária antes de o autor refutá-la.$q$, 3);
select public.fj_seed_q('red', 'red:tese', 'red:tese:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Reconhecer um ponto forte da tese contrária enfraquece automaticamente a argumentação do autor.","a":false}$j$, $q$Falso: a concessão bem refutada demonstra maturidade argumentativa e fortalece a tese.$q$, 2);
select public.fj_seed_q('red', 'red:tese', 'red:tese:2', 3, 'bank', $q$Complete o período com os conectivos adequados$q$, $j${"parts":["É verdade que a tecnologia aproxima pessoas distantes; "," ela também pode isolar quem está perto; "," o uso consciente das telas é indispensável."],"a":["entretanto","por isso"],"extra":["ou seja","caso contrário"]}$j$, $q$Primeiro a oposição (entretanto), depois a conclusão (por isso): é o movimento da concessão refutada.$q$, 2);

