select public.fj_seed_q('red', 'red:conectivos', 'red:conectivos:1', 0, 'mc', $q$Qual conectivo expressa ideia de oposição?$q$, $j${"opts":["Contudo","Portanto","Porque","Assim como"],"a":0}$j$, $q$Contudo, porém, todavia e entretanto introduzem ideias contrárias.$q$, 1);
select public.fj_seed_q('red', 'red:conectivos', 'red:conectivos:1', 1, 'mc', $q$Na frase 'Estudou muito; portanto, foi aprovado', o conectivo 'portanto' indica:$q$, $j${"opts":["Conclusão","Oposição","Condição","Finalidade"],"a":0}$j$, $q$O 'portanto' apresenta a aprovação como consequência lógica do estudo.$q$, 2);
select public.fj_seed_q('red', 'red:conectivos', 'red:conectivos:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Os conectivos 'todavia' e 'portanto' podem ser trocados entre si sem alterar o sentido da frase.","a":false}$j$, $q$Falso: 'todavia' marca oposição e 'portanto' marca conclusão; trocá-los muda a lógica do período.$q$, 2);
