select public.fj_seed_q('red', 'red:conectivos', 'red:conectivos:2', 0, 'mc', $q$Para evitar repetir a palavra 'tecnologia' várias vezes no texto, o autor pode usar:$q$, $j${"opts":["Sinônimos e pronomes, como 'esse recurso' ou 'ela'","A mesma palavra em todas as frases","Somente reticências no lugar do termo","Palavras de sentido oposto"],"a":0}$j$, $q$A substituição por sinônimos e pronomes mantém a referência sem repetição cansativa.$q$, 1);
select public.fj_seed_q('red', 'red:conectivos', 'red:conectivos:2', 1, 'mc', $q$Em 'O Brasil ampliou o acesso à internet. Esse avanço, porém, não alcançou todos', a expressão 'esse avanço' retoma:$q$, $j${"opts":["A ampliação do acesso à internet","O Brasil","A internet em si","As pessoas não alcançadas"],"a":0}$j$, $q$A expressão resume e retoma a ideia da frase anterior: é uma anáfora por resumo.$q$, 3);
select public.fj_seed_q('red', 'red:conectivos', 'red:conectivos:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"A coesão referencial é construída quando pronomes e sinônimos retomam termos já citados no texto.","a":true}$j$, $q$Verdadeiro: a retomada costura as frases e evita repetições.$q$, 1);
select public.fj_seed_q('red', 'red:conectivos', 'red:conectivos:2', 3, 'bank', $q$Complete a frase sobre referenciação$q$, $j${"parts":["A retomada de um termo já citado chama-se "," e o uso de um termo mais genérico no lugar dele, como 'o fenômeno', é uma forma de "," lexical."],"a":["anáfora","substituição"],"extra":["catáfora","elipse"]}$j$, $q$Anáfora olha para trás no texto; a substituição lexical troca o termo por outro equivalente.$q$, 3);
select public.fj_seed_q('red', 'red:coerencia', 'red:coerencia:1', 0, 'mc', $q$O tópico frasal de um parágrafo é:$q$, $j${"opts":["A frase que apresenta a ideia central do parágrafo","Sempre a última frase do parágrafo","Uma citação obrigatória de abertura","O título do texto"],"a":0}$j$, $q$O tópico frasal anuncia o argumento que o parágrafo vai desenvolver.$q$, 1);
select public.fj_seed_q('red', 'red:coerencia', 'red:coerencia:1', 1, 'mc', $q$Um parágrafo de desenvolvimento bem construído na redação do ENEM costuma ter:$q$, $j${"opts":["Tópico frasal, fundamentação com repertório e fechamento","Apenas uma frase bem longa","Somente perguntas retóricas","Vários assuntos diferentes misturados"],"a":0}$j$, $q$Essa sequência garante que o argumento seja anunciado, provado e amarrado à tese.$q$, 2);
select public.fj_seed_q('red', 'red:coerencia', 'red:coerencia:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Cada parágrafo de desenvolvimento deve tratar de um único argumento central.","a":true}$j$, $q$Verdadeiro: um argumento por parágrafo mantém a unidade e a clareza do texto.$q$, 2);
select public.fj_seed_q('red', 'red:coerencia', 'red:coerencia:1', 3, 'order', $q$Ordene as partes de um parágrafo de desenvolvimento$q$, $j${"items":["Tópico frasal com o argumento","Repertório que fundamenta a ideia","Análise ligando o repertório ao tema","Fechamento que retoma a tese"]}$j$, $q$Anuncia, prova, analisa e conclui: é o caminho natural do parágrafo argumentativo.$q$, 2);
select public.fj_seed_q('red', 'red:coerencia', 'red:coerencia:2', 0, 'mc', $q$Um texto perde coerência quando:$q$, $j${"opts":["Defende uma ideia e depois a contradiz sem justificar","Usa conectivos variados","Apresenta exemplos ligados à tese","Mantém o mesmo ponto de vista do início ao fim"],"a":0}$j$, $q$Coerência é a lógica interna do texto: ideias que se anulam quebram essa lógica.$q$, 2);
select public.fj_seed_q('red', 'red:coerencia', 'red:coerencia:2', 1, 'mc', $q$Afirmar na introdução que 'a escola resolve tudo' e concluir que 'a escola é incapaz de agir' é um problema de:$q$, $j${"opts":["Contradição argumentativa","Coesão referencial","Ortografia","Pontuação"],"a":0}$j$, $q$As duas afirmações se anulam: o leitor não sabe mais qual é a posição do autor.$q$, 3);
select public.fj_seed_q('red', 'red:coerencia', 'red:coerencia:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Coerência é a relação lógica entre as ideias do texto, que não podem se contradizer.","a":true}$j$, $q$Verdadeiro: a coerência garante que o texto faça sentido como um todo.$q$, 1);
select public.fj_seed_q('red', 'red:coerencia', 'red:coerencia:2', 3, 'match', $q$Associe o problema textual à sua descrição$q$, $j${"pairs":[["Contradição","Ideias que se anulam no mesmo texto"],["Circularidade","Repetir a tese sem fazer o texto avançar"],["Fuga ao tema","Tratar de assunto diferente do proposto"],["Quebra de progressão","Parágrafos sem ligação entre si"]]}$j$, $q$Reconhecer esses defeitos ajuda a revisar o próprio texto antes de entregá-lo.$q$, 3);

-- SEÇÃO: Repertório sociocultural
select public.fj_seed_q('red', 'red:repertorios', 'red:repertorios:1', 0, 'mc', $q$O repertório sociocultural é considerado produtivo quando:$q$, $j${"opts":["É relacionado ao tema e fundamenta o argumento","Aparece solto, apenas para enfeitar o texto","É citado sem nenhuma análise","Substitui a tese do autor"],"a":0}$j$, $q$Repertório produtivo é o que trabalha a favor do argumento, com análise que o conecta ao tema.$q$, 2);
select public.fj_seed_q('red', 'red:repertorios', 'red:repertorios:1', 1, 'mc', $q$Ao citar o filme 'Que Horas Ela Volta?' em uma redação sobre desigualdade, o candidato deve:$q$, $j${"opts":["Relacionar a obra ao argumento, explicando o que ela ilustra","Resumir o filme inteiro","Apenas mencionar o título, sem comentário","Copiar falas longas dos personagens"],"a":0}$j$, $q$Vale a análise, não a menção: a obra precisa iluminar o argumento do texto.$q$, 2);
select public.fj_seed_q('red', 'red:repertorios', 'red:repertorios:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Para valer na competência 2, o repertório precisa ser legitimado, ter relação com o tema e ser usado de forma produtiva.","a":true}$j$, $q$Verdadeiro: são os três critérios que a banca aplica ao repertório.$q$, 2);
select public.fj_seed_q('red', 'red:repertorios', 'red:repertorios:1', 3, 'bank', $q$Complete a frase sobre o bom uso do repertório$q$, $j${"parts":["Um repertório bem usado é "," ao tema e vem acompanhado de "," que o conecta ao argumento."],"a":["pertinente","análise"],"extra":["alheio","cópia"]}$j$, $q$Pertinência e análise transformam a citação em prova do argumento.$q$, 1);
select public.fj_seed_q('red', 'red:repertorios', 'red:repertorios:2', 0, 'mc', $q$Qual das opções é um repertório legitimado?$q$, $j${"opts":["Um conceito do filósofo Michel Foucault","Um boato de rede social sem fonte","Uma opinião anônima da internet","Um achismo pessoal do candidato"],"a":0}$j$, $q$Legitimado é o repertório com fonte reconhecida: pensadores, obras, leis e dados oficiais.$q$, 2);
select public.fj_seed_q('red', 'red:repertorios', 'red:repertorios:2', 1, 'mc', $q$Frases como 'desde sempre o mundo é assim' enfraquecem a redação porque:$q$, $j${"opts":["Expressam senso comum, sem comprovação ou fonte","São longas demais","Usam linguagem formal","Contêm dados numéricos"],"a":0}$j$, $q$O senso comum não tem valor de prova: a banca espera conhecimento de áreas legitimadas.$q$, 3);
select public.fj_seed_q('red', 'red:repertorios', 'red:repertorios:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Livros, leis, filmes, dados oficiais e pensadores são exemplos de repertório legitimado.","a":true}$j$, $q$Verdadeiro: todos vêm de áreas do conhecimento reconhecidas socialmente.$q$, 1);
select public.fj_seed_q('red', 'red:repertorios', 'red:repertorios:2', 3, 'match', $q$Associe o repertório à área de onde ele vem$q$, $j${"pairs":[["1984, de George Orwell","Literatura"],["Constituição de 1988","Legislação"],["Dados do IBGE","Estatística oficial"],["Hannah Arendt","Filosofia"]]}$j$, $q$Variar as áreas do repertório enriquece a argumentação e mostra amplitude de leitura.$q$, 2);
select public.fj_seed_q('red', 'red:temas', 'red:temas:1', 0, 'mc', $q$A Constituição de 1988 é chamada de 'Constituição Cidadã' porque:$q$, $j${"opts":["Ampliou direitos sociais e garantias individuais","Criou a primeira capital do país","Aboliu a escravidão","Instituiu o voto censitário"],"a":0}$j$, $q$Promulgada após a ditadura, ela consagrou direitos como saúde, educação e voto universal.$q$, 1);
select public.fj_seed_q('red', 'red:temas', 'red:temas:1', 1, 'mc', $q$Em temas sociais do ENEM, citar o artigo 5º da Constituição é útil para tratar de:$q$, $j${"opts":["Igualdade e direitos fundamentais","Normas ortográficas","Política cambial","Divisão administrativa dos municípios"],"a":0}$j$, $q$O artigo 5º garante que todos são iguais perante a lei: repertório coringa para temas de inclusão.$q$, 2);
select public.fj_seed_q('red', 'red:temas', 'red:temas:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"A Declaração Universal dos Direitos Humanos, de 1948, pode servir de repertório em temas sobre dignidade e inclusão.","a":true}$j$, $q$Verdadeiro: é um documento internacional legitimado e aplicável a muitos temas sociais.$q$, 2);
select public.fj_seed_q('red', 'red:temas', 'red:temas:1', 3, 'bank', $q$Complete a frase sobre conceitos úteis em temas sociais$q$, $j${"parts":["O conceito de "," de Zygmunt Bauman, descreve relações frágeis na sociedade atual, e a noção de cidadania envolve direitos e "," de cada indivíduo."],"a":["modernidade líquida","deveres"],"extra":["mais-valia","impostos"]}$j$, $q$Bauman cunhou a modernidade líquida; cidadania é sempre o par direitos e deveres.$q$, 3);
select public.fj_seed_q('red', 'red:temas', 'red:temas:2', 0, 'mc', $q$Para um tema sobre mobilidade urbana, um repertório pertinente seria:$q$, $j${"opts":["Dados sobre o tempo médio gasto no transporte público","A biografia de um jogador de futebol","Uma receita culinária tradicional","Um poema sobre o mar"],"a":0}$j$, $q$O repertório precisa dialogar com o tema: dados de transporte sustentam o debate sobre mobilidade.$q$, 2);
select public.fj_seed_q('red', 'red:temas', 'red:temas:2', 1, 'mc', $q$Em temas de educação, é repertório clássico citar:$q$, $j${"opts":["Paulo Freire e sua defesa da educação libertadora","Um influenciador anônimo","Uma propaganda de cursinho","O senso comum de que estudar cansa"],"a":0}$j$, $q$Paulo Freire é referência mundial em educação e repertório legitimado para o tema.$q$, 2);
select public.fj_seed_q('red', 'red:temas', 'red:temas:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Um mesmo repertório, como a Constituição de 1988, pode ser adaptado a vários temas sociais diferentes.","a":true}$j$, $q$Verdadeiro: o que muda é a análise que liga o repertório a cada tema.$q$, 1);
select public.fj_seed_q('red', 'red:temas', 'red:temas:2', 3, 'match', $q$Associe o tema recorrente a um repertório clássico$q$, $j${"pairs":[["Saúde mental","Sociedade do cansaço, de Byung-Chul Han"],["Educação","Paulo Freire"],["Desigualdade","Dados do IBGE sobre renda"],["Democracia","Constituição de 1988"]]}$j$, $q$Montar um banco de repertórios por tema agiliza a escrita no dia da prova.$q$, 3);

