select public.fj_seed_q('red', 'red:tipostextuais', 'red:tipostextuais:1', 0, 'mc', $q$O tipo textual que expõe e defende um ponto de vista com argumentos é o:$q$, $j${"opts":["Dissertativo-argumentativo","Narrativo","Descritivo","Injuntivo"],"a":0}$j$, $q$Dissertar e argumentar é expor ideias e sustentá-las: o tipo exigido na redação do ENEM.$q$, 1);
select public.fj_seed_q('red', 'red:tipostextuais', 'red:tipostextuais:1', 1, 'mc', $q$Um manual de instruções, que orienta o leitor a executar ações, é um texto predominantemente:$q$, $j${"opts":["Injuntivo","Narrativo","Dissertativo","Descritivo"],"a":0}$j$, $q$O tipo injuntivo instrui e orienta, geralmente com verbos no imperativo.$q$, 2);
select public.fj_seed_q('red', 'red:tipostextuais', 'red:tipostextuais:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"O texto narrativo se organiza em torno de personagens e ações que se desenrolam no tempo.","a":true}$j$, $q$Verdadeiro: narrar é contar fatos encadeados no tempo, com personagens e enredo.$q$, 1);
select public.fj_seed_q('red', 'red:tipostextuais', 'red:tipostextuais:1', 3, 'match', $q$Associe o tipo textual à sua função$q$, $j${"pairs":[["Narrar","Contar fatos no tempo"],["Descrever","Caracterizar seres, lugares e cenas"],["Dissertar","Expor e defender ideias"],["Injuntivo","Instruir e orientar ações"]]}$j$, $q$Os tipos textuais são as bases que se combinam nos diferentes gêneros.$q$, 2);
select public.fj_seed_q('red', 'red:tipostextuais', 'red:tipostextuais:2', 0, 'mc', $q$Qual gênero jornalístico tem como objetivo principal opinar sobre um fato?$q$, $j${"opts":["Artigo de opinião","Notícia","Classificados","Previsão do tempo"],"a":0}$j$, $q$O artigo de opinião é assinado e defende abertamente o ponto de vista do autor.$q$, 1);
select public.fj_seed_q('red', 'red:tipostextuais', 'red:tipostextuais:2', 1, 'mc', $q$A diferença básica entre notícia e reportagem é que a reportagem:$q$, $j${"opts":["Aprofunda o fato com contexto, dados e entrevistas","É sempre menor que a notícia","Dispensa apuração","Traz apenas a opinião do autor"],"a":0}$j$, $q$A notícia relata o fato recente; a reportagem o investiga com mais profundidade.$q$, 2);
select public.fj_seed_q('red', 'red:tipostextuais', 'red:tipostextuais:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"A notícia, por definição, deve apresentar abertamente a opinião pessoal do jornalista.","a":false}$j$, $q$Falso: a notícia busca a objetividade; a opinião pertence a gêneros como o artigo e o editorial.$q$, 2);
select public.fj_seed_q('red', 'red:tipostextuais', 'red:tipostextuais:2', 3, 'bank', $q$Complete a frase sobre gêneros jornalísticos$q$, $j${"parts":["O "," é o gênero que expressa a opinião oficial do jornal, enquanto a "," relata o fato de forma objetiva."],"a":["editorial","notícia"],"extra":["crônica","carta do leitor"]}$j$, $q$Editorial: voz do veículo, sem assinatura. Notícia: relato objetivo do fato.$q$, 2);
select public.fj_seed_q('red', 'red:dissertativo', 'red:dissertativo:1', 0, 'mc', $q$A estrutura clássica da redação do ENEM é composta por:$q$, $j${"opts":["Introdução, desenvolvimento e conclusão","Apenas introdução e conclusão","Versos e estrofes","Diálogos entre personagens"],"a":0}$j$, $q$O modelo mais seguro tem 4 parágrafos: introdução, dois desenvolvimentos e conclusão.$q$, 1);
select public.fj_seed_q('red', 'red:dissertativo', 'red:dissertativo:1', 1, 'mc', $q$Na conclusão da redação do ENEM, é obrigatório apresentar:$q$, $j${"opts":["Uma proposta de intervenção para o problema","Um argumento totalmente novo","Uma pergunta sem resposta","Um resumo do repertório usado"],"a":0}$j$, $q$A competência 5 avalia justamente a proposta de intervenção apresentada na conclusão.$q$, 2);
select public.fj_seed_q('red', 'red:dissertativo', 'red:dissertativo:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"A redação do ENEM deve ser escrita em prosa; um texto feito todo em versos é anulado.","a":true}$j$, $q$Verdadeiro: texto predominantemente em versos recebe nota zero na prova.$q$, 2);
select public.fj_seed_q('red', 'red:dissertativo', 'red:dissertativo:1', 3, 'order', $q$Ordene as partes da redação dissertativo-argumentativa$q$, $j${"items":["Introdução com contextualização e tese","Primeiro parágrafo de desenvolvimento","Segundo parágrafo de desenvolvimento","Conclusão com proposta de intervenção"]}$j$, $q$Essa sequência organiza o projeto de texto do início ao fim.$q$, 1);
