select public.fj_seed_q('red', 'red:dissertativo', 'red:dissertativo:2', 1, 'mc', $q$Na proposta 'o Ministério da Educação deve criar campanhas, por meio da mídia, a fim de conscientizar os jovens', falta o elemento:$q$, $j${"opts":["Detalhamento","Agente","Ação","Finalidade"],"a":0}$j$, $q$Há agente, ação, meio e finalidade, mas nenhum deles é aprofundado ou especificado.$q$, 3);
select public.fj_seed_q('red', 'red:dissertativo', 'red:dissertativo:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"A proposta de intervenção deve respeitar os direitos humanos para não perder pontos na competência 5.","a":true}$j$, $q$Verdadeiro: propostas que ferem direitos humanos zeram a competência 5.$q$, 2);
select public.fj_seed_q('red', 'red:dissertativo', 'red:dissertativo:2', 3, 'match', $q$Associe o elemento da proposta à pergunta que ele responde$q$, $j${"pairs":[["Agente","Quem vai agir?"],["Ação","O que será feito?"],["Meio","Como será feito?"],["Finalidade","Para quê?"]]}$j$, $q$Responder a essas perguntas garante uma proposta completa, junto do detalhamento.$q$, 2);

