-- SEÇÃO: Estruturas verbais
select public.fj_seed_q('ing', 'ing:tempos', 'ing:tempos:1', 0, 'mc', $q$Na frase "She is studying for the ENEM right now", o present continuous indica:$q$, $j${"opts":["Uma ação em andamento no momento da fala","Um hábito que se repete todos os dias","Uma ação concluída no passado","Uma possibilidade remota no futuro"],"a":0}$j$, $q$O present continuous (be + verbo-ing) descreve o que está acontecendo agora.$q$, 1);
select public.fj_seed_q('ing', 'ing:tempos', 'ing:tempos:1', 1, 'mc', $q$Qual frase expressa um plano futuro já decidido?$q$, $j${"opts":["We are going to travel to Recife next month.","We traveled to Recife last month.","We used to travel to Recife every year.","We were traveling to Recife yesterday."],"a":0}$j$, $q$"Be going to" indica uma intenção ou plano já decidido para o futuro.$q$, 2);
select public.fj_seed_q('ing', 'ing:tempos', 'ing:tempos:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"O present continuous também pode indicar um compromisso futuro já combinado, como em 'I am meeting her tomorrow'.","a":true}$j$, $q$Verdadeiro: com marcadores de tempo futuro, o present continuous indica planos agendados.$q$, 2);
select public.fj_seed_q('ing', 'ing:tempos', 'ing:tempos:1', 3, 'bank', $q$Complete a frase em inglês$q$, $j${"parts":["Look at those clouds! It is "," rain, so take your "," with you."],"a":["going to","umbrella"],"extra":["went to","sunglasses"]}$j$, $q$"Going to" é usado para previsões com evidências; guarda-chuva combina com chuva.$q$, 2);
select public.fj_seed_q('ing', 'ing:tempos', 'ing:tempos:2', 0, 'mc', $q$Na frase "I was reading when the phone rang", o past continuous descreve:$q$, $j${"opts":["Uma ação em andamento interrompida por outra","Duas ações que ainda vão acontecer","Um hábito do presente","Uma ordem dada no passado"],"a":0}$j$, $q$O past continuous mostra a ação mais longa que foi interrompida pela mais curta.$q$, 2);
select public.fj_seed_q('ing', 'ing:tempos', 'ing:tempos:2', 1, 'mc', $q$Qual alternativa indica um hábito do passado que não existe mais?$q$, $j${"opts":["She used to play soccer every weekend.","She is playing soccer now.","She will play soccer tomorrow.","She has just finished playing soccer."],"a":0}$j$, $q$"Used to" descreve hábitos ou estados do passado que acabaram.$q$, 1);
select public.fj_seed_q('ing', 'ing:tempos', 'ing:tempos:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"A expressão 'used to' é empregada para descrever ações que acontecem rotineiramente no presente.","a":false}$j$, $q$Falso: 'used to' fala de hábitos do passado; rotinas do presente usam o simple present.$q$, 2);
select public.fj_seed_q('ing', 'ing:tempos', 'ing:tempos:2', 3, 'order', $q$Coloque as palavras na ordem correta para formar a frase em inglês$q$, $j${"items":["They","were watching","a movie","last night."]}$j$, $q$Sujeito + was/were + verbo-ing + complemento: They were watching a movie last night.$q$, 1);
select public.fj_seed_q('ing', 'ing:estruturas', 'ing:estruturas:1', 0, 'mc', $q$Na frase "If it rains, we will stay home", a condição expressa é:$q$, $j${"opts":["Uma situação possível no futuro (first conditional)","Uma situação impossível no passado","Apenas um fato científico","Um arrependimento do falante"],"a":0}$j$, $q$First conditional: if + presente simples, will + verbo, para situações prováveis.$q$, 2);
select public.fj_seed_q('ing', 'ing:estruturas', 'ing:estruturas:1', 1, 'mc', $q$Qual frase é um exemplo de second conditional, usado para situações hipotéticas?$q$, $j${"opts":["If I had more money, I would travel the world.","If you heat ice, it melts.","If she calls, I will answer.","When I arrive, I always take a shower."],"a":0}$j$, $q$Second conditional: if + passado simples, would + verbo, para hipóteses improváveis.$q$, 3);
select public.fj_seed_q('ing', 'ing:estruturas', 'ing:estruturas:1', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"No zero conditional, usado para verdades gerais, as duas orações ficam no presente simples, como em 'If you mix blue and yellow, you get green'.","a":true}$j$, $q$Verdadeiro: o zero conditional expressa fatos que sempre acontecem.$q$, 2);
select public.fj_seed_q('ing', 'ing:estruturas', 'ing:estruturas:1', 3, 'bank', $q$Complete a frase hipotética em inglês$q$, $j${"parts":["If I "," rich, I "," buy a big house by the sea."],"a":["were","would"],"extra":["am","will"]}$j$, $q$No second conditional usamos 'were' e 'would' para falar de algo hipotético.$q$, 3);
